from pathlib import Path
import hashlib,json,struct,sys
R=Path(__file__).resolve().parents[2]
def sha(p):
 with Path(p).open('rb')as f:return hashlib.file_digest(f,'sha256').hexdigest()
def main():
 out=R/'reports/m4-loader-message-review/native-preparation-r1';assert not out.exists();out.mkdir();pins={}
 def pin(p,h=None):p=Path(p).resolve();actual=sha(p);assert h is None or actual==h;pins[str(p)]=actual;return p
 proof=pin(R/'reports/m4-loader-message-review/physical-r4/report.json','138452ce77ef212ca239499794e0aa9e4a6034a64361a70fc71b0896205959e4');d=json.loads(proof.read_bytes());assert d['passed']and not d['native_executed']
 for p,h in d['files'].items():pin(p,h)
 import importlib.util
 p=pin(R/'tools/analysis/pe.py');spec=importlib.util.spec_from_file_location('message_prepare_PE',p);PE=importlib.util.module_from_spec(spec);spec.loader.exec_module(PE);source=pin(R/'MW3/Mech3Msg.dll','8899fabb7e57383a9a483cb048636bcc027334b48941aa49835cdcc1c4715b8c');image=PE.PEImage(source.read_bytes())
 table=json.loads(pin(proof.parent/'current-name-id-table.json').read_bytes());assert len(table['rows'])==1577 and len({r['name']for r in table['rows']})==1577;data=image.read(image.rva_range(0x3000,45776)[0],45776)
 header=out/'source_table.hpp';header.write_text('#pragma once\nstatic const unsigned char source_data[] = {'+','.join(str(x)for x in data)+'};\nstatic const unsigned source_pairs[1577][2] = {'+','.join('{'+str(r['name_pointer'])+','+str(r['id'])+'}'for r in table['rows'])+'};\n');pin(header)
 code=pin(Path(__file__).with_name('native_provider.cpp'));native=out/'native_provider.cpp';native.write_bytes(code.read_bytes());pin(native)
 resources=json.loads(pin(proof.parent/'current-resources.json').read_bytes());assert len(resources)==1 and resources[0]['path']==[11,1,1033];payload=pin(resources[0]['payload_path'],resources[0]['sha256']).read_bytes();assert len(payload)==68528
 # Standard Win32 .res encoding: ordinal RT_MESSAGETABLE11, ID1, LANG1033.
 null=struct.pack('<IIHHHHIHHII',0,32,0xffff,0,0xffff,0,0,0,0,0,0)
 h=struct.pack('<IIHHHHIHHII',len(payload),32,0xffff,11,0xffff,1,0,0x1030,1033,0,0)
 resource=out/'messages.res';resource.write_bytes(null+h+payload+b'\0'*((-len(payload))%4));pin(resource)
 design=dict(scope='Compile-only executable x64 message module candidate, no accepted-game/native-load credit',source_identity=sha(source),source_architecture='PE32 i386',native_architecture='PE32+ AMD64',source_module_base=0x10000000,source_export_rva=0x1720,source_entry_rva=0x1b30,source_table_pairs=1577,source_table_bytes=12616,source_whole_data_bytes=45776,source_message_leaf=dict(type=11,id=1,language=1033,bytes=68528,sha256=resources[0]['sha256']),native_DLL_main_effects=['Actual own host CRT malloc128/firstDWORDzero; failure returnsFALSE','Whole authentic initial1577 pairs loaded from physical source table','Unsigned byte string order over authenticated entire source data names','Every DLL notification sorts; native own detach frees wide host CRT pointer'],required_projection_contract=['Native HMODULE/FARPROC/CRT pointers remain uintptr_t or typed pointers; never truncate','Original selected Mech3Msg.dll identity8899... distinct from staged1540-message variant','Explicit bare-name source CWD/search selection and derived-native file relation, pinned module/import/provider path and generation','Native LoadLibraryA/GetProcAddress must actually execute candidate entry; datafile substitute forbidden','Guest HMODULE and source base+1720 export address are typed aliases/projections to genuine owning native64 module/export with exact source-site/frame evidence','GetProcAddress missing does not change source success; sourcelocale zero store/globalmodule/globalexport timing retained','Capture incoming/outgoing LastError immediately around each actual API before diagnostics; retain authentic module and resources through source lifetime'],frontiers=['This independent endpoint insertion-sort is not a literal quicksort execution proof; sorted unique-permutation equivalence still requires independent review','Host CRT allocation/runtime startup does not prove original MSVCRT128 exit table, _adjust_fdiv value, FS/SEH/CPU/FX side effects or imported DLL initialization parity','Source raw-hook0/oneNULL initializer slot/empty exit registry bind current clean image only; indirect callbacks remain declared outside that frontier','No original/native47F760 worker exists for this component; callback/input/state/source paired execution and lifetime proof pending','Future exported function invocation requires owned string and cdecl32-to-native64 frame/return/value relation; normalroot resolves but does not call it','Actual resource extraction/type/id/language/hash and whole1577 sorted-table snapshot from loaded DLL still pending root-approved runtime controls'],no_DLL_execution=True,source_algorithm_executed=False,initializer_credit=0)
 p=out/'design.json';p.write_text(json.dumps(design,indent=2)+'\n');pin(p);pin(__file__);pin(sys.executable)
 q=out/'report.json';q.write_text(json.dumps(dict(passed=True,scope=design['scope'],files=pins,no_DLL_execution=True,initializer_credit=0),indent=2)+'\n');print(json.dumps(dict(passed=True,sha256=sha(q))))
